import { MeshBasicNodeMaterial, MeshStandardNodeMaterial } from 'three/webgpu';
import { gsap } from 'gsap';
import { } } from '@/primitives';
import { } } from '@/text';

/**
 * @typedef {Object} NodeConfig
 * @property {string} [imageUrl]
 * @property {Object} [intent]
 * @property {Object} [intent.visualSpec]
 * @property {Object} [intent.visualSpec.colors]
 * @property {Array} [cinematicPrimitives]
 * @property {Array} [textContent]
 */

/**
 * @typedef {Object} NodeContext
 * @property {Object} THREE
 * @property {Object} textureLoader
 * @property {Object} glbLoader
 * @property {Object} [videoLoader]
 * @property {Object} fontAtlas
 * @property {Object} primitives
 * @property {Function} emit
 * @property {string} [tier]
 */

/**
 * @param {NodeConfig} config
 * @param {NodeContext} ctx
 * @returns {THREE.Object3D}
 */
export default function createNode(config, ctx) {
  const { Group, Mesh, PlaneGeometry } = ctx.THREE;

  // Root container
  const root = new Group();

  // Base plane geometry (capsule label)
  const planeGeom = new PlaneGeometry(1, 0.4);
  const planeMat = new MeshBasicNodeMaterial();
  const plane = new Mesh(planeGeom, planeMat);
  root.add(plane);

  // Load texture if provided
  if (config.imageUrl) {
    ctx.textureLoader.loadTexture(config.imageUrl).then((tex) => {
      planeMat.map = tex;
      planeMat.needsUpdate = true;
    });
  }

  // Accent edge – slightly larger plane with emissive material
  const edgeGeom = new PlaneGeometry(1.02, 0.42);
  const accentColor =
    config.intent?.visualSpec?.colors?.accent || '#ff2a38';
  const edgeMat = new MeshStandardNodeMaterial({
    color: 0x000000,
    emissiveColor: accentColor,
    emissiveIntensity: 1.5,
    transparent: true,
    opacity: 0,
  });
  const edge = new Mesh(edgeGeom, edgeMat);
  edge.position.set(0, 0, 0.01);
  root.add(edge);

  // Store timelines for cleanup
  const activeTimelines = [];

  // Event handlers
  const handlers = {};

  // Hover lift (rise‑in)
  handlers.hover = () => {
    const tl = gsap.timeline();
    tl.to(plane.position, {
      y: 0.15,
      duration: 0.7,
      ease: 'power3.out',
    });
    tl.to(
      edgeMat,
      { opacity: 0.8, duration: 0.7, ease: 'power3.out' },
      0
    );
    activeTimelines.push(tl);
  };

  // Unhover revert
  handlers.unhover = () => {
    const tl = gsap.timeline();
    tl.to(plane.position, {
      y: 0,
      duration: 0.7,
      ease: 'power3.out',
    });
    tl.to(
      edgeMat,
      { opacity: 0, duration: 0.7, ease: 'power3.out' },
      0
    );
    activeTimelines.push(tl);
  };

  // Click emit
  handlers.click = () => {
    ctx.emit('hub-collection.select', {});
  };

  // Attach handlers to userData
  root.userData.handlers = handlers;

  // Cleanup routine
  root.userData.cleanup = () => {
    // Dispose geometries and materials
    planeGeom.dispose();
    planeMat.dispose();
    edgeGeom.dispose();
    edgeMat.dispose();

    // Kill any GSAP timelines
    activeTimelines.forEach((tl) => tl.kill());
  };

  // Apply any cinematic primitives listed in config
  if (Array.isArray(config.cinematicPrimitives)) {
    config.cinematicPrimitives.forEach((prim) => {
      const primitive = ctx.primitives[prim.name];
      if (primitive) {
        const instance = primitive(root, prim.params);
        // Store cleanup for the primitive
        const prevCleanup = root.userData.cleanup;
        root.userData.cleanup = () => {
          if (typeof prevCleanup === 'function') prevCleanup();
          instance.cleanup && instance.cleanup();
        };
      }
    });
  }

  return root;
}
